func (this *Test_org_eclipse_swt_graphics_TextLayout) Test_Bug579335_win32_StyledText_LongLine() {
	if !SwtTestUtilIsWindows {
		if SwtTestUtilVerbose {
			fmt.Fprintln(os.Stdout, "Excluded test_Bug579335_win32_StyledText_LongLine(org.eclipse.swt.tests.junit.Test_org_eclipse_swt_graphics_TextLayout).")
		}
		return
	}
	var font *swt.Font = nil
	var image *swt.Image = nil
	var layout *swt.TextLayout = nil
	{
		defer func() {
			if layout != (nil) {
				layout.Dispose()
			}
			if image != (nil) {
				image.Dispose()
			}
			if font != (nil) {
				font.Dispose()
			}
		}()
		font = swt.NewFontDeviceNameHeightStyle(upcastswtDisplayToswtDevice(this.display), SwtTestUtilTestFontName, 16, swt.NORMAL)
		layout = swt.NewTextLayout(upcastswtDisplayToswtDevice(this.display))
		layout.SetFont(font)
		layout.SetText(func() string { _ = []any{"a", 33000}; panic("j2go: unresolved call repeat") }())
		var red *swt.Color = this.display.GetSystemColor(swt.COLOR_RED)
		var white *swt.Color = this.display.GetSystemColor(swt.COLOR_WHITE)
		var green *swt.Color = this.display.GetSystemColor(swt.COLOR_GREEN)
		var redStyle *swt.TextStyle = swt.NewTextStyleFontForegroundBackground(font, red, white)
		var greenStyle *swt.TextStyle = swt.NewTextStyleFontForegroundBackground(font, green, white)
		image = this.Draw(layout, swt.DEFAULT)
		image.Dispose()
		layout.SetStyle(redStyle, 7, 7)
		layout.SetStyle(greenStyle, 8, 8+32909-1)
		image = this.Draw(layout, swt.DEFAULT)
		image.Dispose()
		layout.SetStyle(nil, 0, 33000-1)
		layout.SetStyle(greenStyle, 2, 2+16000-1)
		image = this.Draw(layout, swt.DEFAULT)
		image.Dispose()
		layout.SetStyle(nil, 0, 33000-1)
		layout.SetStyle(redStyle, 0, 0+1-1)
		layout.SetStyle(greenStyle, 1, 1+32916-1)
		image = this.Draw(layout, swt.DEFAULT)
	}
}

